window.GH600 = {"domains": {"1": "Prepare agent architecture and SDLC processes", "2": "Implement tool use and environment interaction", "3": "Manage memory, state, and execution", "4": "Perform evaluation, error analysis, and tuning", "5": "Orchestrate multi-agent coordination", "6": "Implement guardrails and accountability"}, "weights": {"1": 0.175, "2": 0.225, "3": 0.125, "4": 0.175, "5": 0.175, "6": 0.125}, "cards": [{"id": "D1-C01", "d": 1, "front": "Delegate-to-agent rule of thumb?", "back": "Delegate when success is checkable automatically and failure is cheap to undo (well-scoped, verifiable, reversible)."}, {"id": "D1-C02", "d": 1, "front": "Name 3 good first tasks for a coding agent.", "back": "Tests for existing code, bug fixes with a failing repro, docs/dependency bumps/mechanical refactors."}, {"id": "D1-C03", "d": 1, "front": "Name 3 poor candidates for autonomous delegation.", "back": "Ambiguous requirements, cross-service architecture redesign, irreversible/production-affecting or security-critical work without review."}, {"id": "D1-C04", "d": 1, "front": "Anti-pattern: no definition of done. Mitigation?", "back": "Task template with objective acceptance criteria (tests, scans, scope limits)."}, {"id": "D1-C05", "d": 1, "front": "Anti-pattern: one agent plans, codes, reviews and deploys. Mitigation?", "back": "Separate roles / separation of duties (planner, executor, reviewer)."}, {"id": "D1-C06", "d": 1, "front": "Three parts of a well-defined agent task?", "back": "Inputs (goal, scope, constraints), outputs (draft PR, tests, log), success criteria (checkable)."}, {"id": "D1-C07", "d": 1, "front": "How do you technically keep a planner from editing code?", "back": "Give it read/search tools only (tool restriction in the custom agent)."}, {"id": "D1-C08", "d": 1, "front": "Why should a plan be structured?", "back": "So it can be validated (by people or automation) and compared with the final diff."}, {"id": "D1-C09", "d": 1, "front": "What does 'validate the plan' check?", "back": "Referenced files/tests exist, scope matches the task, criteria are met, risks and rollback noted."}, {"id": "D1-C10", "d": 1, "front": "How do you prevent action until a plan is approved?", "back": "A gate: approval label/comment/environment/re-assignment; executor write tools only enabled after approval."}, {"id": "D1-C11", "d": 1, "front": "Planning vs reasoning vs action?", "back": "Planning/reasoning are read-only analysis producing a plan; action mutates state (edit, commit, push, write tools)."}, {"id": "D1-C12", "d": 1, "front": "Best natural checkpoint for human review of agent work on GitHub?", "back": "The (draft) pull request."}, {"id": "D1-C13", "d": 1, "front": "List inspectable artifacts from a cloud agent run.", "back": "Draft PR, co-authored signed commits, session logs, comments, Actions logs and scan results."}, {"id": "D1-C14", "d": 1, "front": "How to add human oversight without slowing delivery?", "back": "Review at PR boundary, CODEOWNERS/rulesets for sensitive paths, async steering, auto-allow low-risk read-only actions."}, {"id": "D1-C15", "d": 1, "front": "Why is 'approve every tool call' an anti-pattern?", "back": "It slows delivery without materially reducing risk; approvals should be risk-proportional."}, {"id": "D1-C16", "d": 1, "front": "Repo-wide instruction file path?", "back": ".github/copilot-instructions.md"}, {"id": "D1-C17", "d": 1, "front": "Path-specific instruction files?", "back": ".github/instructions/*.instructions.md with applyTo frontmatter."}, {"id": "D1-C18", "d": 1, "front": "Where do repo-level custom agents live?", "back": ".github/agents/ (*.agent.md files). Org-level agents use the github-private repo."}, {"id": "D1-C19", "d": 1, "front": "What role does GitHub play for agents on this exam?", "back": "System of record and control plane: issues, branches, PRs, Actions, rulesets, session logs."}, {"id": "D1-C20", "d": 1, "front": "Strong vs weak success criteria?", "back": "Strong: 'failing test added and passing, suite green, no new CodeQL alerts, only src/billing changed'. Weak: 'make it work'."}, {"id": "D2-C01", "d": 2, "front": "Where do you configure MCP servers for cloud agent at repo level?", "back": "Repo Settings > Copilot > MCP servers, as JSON with a top-level mcpServers object."}, {"id": "D2-C02", "d": 2, "front": "Required MCP config keys for cloud agent?", "back": "type (local, stdio, http, sse) and tools (list of tool names or [\"*\"])."}, {"id": "D2-C03", "d": 2, "front": "Local MCP server keys?", "back": "command, args, optional env."}, {"id": "D2-C04", "d": 2, "front": "Remote MCP server keys?", "back": "url and optional headers."}, {"id": "D2-C05", "d": 2, "front": "Secret/variable naming for MCP config?", "back": "Agents secrets/variables whose names start with COPILOT_MCP_; referenced as $VAR, ${VAR} or ${VAR:-default}."}, {"id": "D2-C06", "d": 2, "front": "Why allowlist specific read-only tools?", "back": "Copilot uses configured MCP tools autonomously and does not ask for approval first."}, {"id": "D2-C07", "d": 2, "front": "MCP limits for cloud agent and code review?", "back": "Tools only (no resources/prompts) and no remote servers requiring OAuth."}, {"id": "D2-C08", "d": 2, "front": "Which MCP servers are on by default for cloud agent?", "back": "GitHub MCP server and Playwright MCP server."}, {"id": "D2-C09", "d": 2, "front": "Default GitHub MCP token scope?", "back": "Read-only, current repository only. Use a fine-grained PAT or GitHub App for wider access."}, {"id": "D2-C10", "d": 2, "front": "Remote GitHub MCP URLs?", "back": "https://api.githubcopilot.com/mcp/ and the read-only https://api.githubcopilot.com/mcp/readonly"}, {"id": "D2-C11", "d": 2, "front": "How do you select toolsets on the remote GitHub MCP server?", "back": "X-MCP-Toolsets header (for example repos,issues,pull_requests); pick individual tools with the tools field."}, {"id": "D2-C12", "d": 2, "front": "How do you validate MCP config?", "back": "Assign an issue to Copilot, View session, open the 'Start MCP Servers' step in the log and check the listed tools."}, {"id": "D2-C13", "d": 2, "front": "Code review MCP tool requirement?", "back": "Each tool must set annotations.readOnlyHint to true or it is excluded."}, {"id": "D2-C14", "d": 2, "front": "Where is the environment setup workflow and what must the job be called?", "back": ".github/workflows/copilot-setup-steps.yml, job name copilot-setup-steps."}, {"id": "D2-C15", "d": 2, "front": "MCP server needs uv or pipx that is not on the runner. Fix?", "back": "Install it in copilot-setup-steps.yml."}, {"id": "D2-C16", "d": 2, "front": "Agent blocked by firewall on one host. Fix?", "back": "Add that host to the custom allowlist; do not disable the firewall."}, {"id": "D2-C17", "d": 2, "front": "Which branch can cloud agent push to?", "back": "One branch: a new copilot/ branch, or the PR branch when @copilot is mentioned on an existing PR. Branch protections still apply."}, {"id": "D2-C18", "d": 2, "front": "What can't cloud agent do to its own PR?", "back": "Mark Ready for review, approve, or merge. It also cannot run arbitrary git commands."}, {"id": "D2-C19", "d": 2, "front": "Do workflows run on agent PRs automatically?", "back": "No (default). A user with write access must click Approve and run workflows."}, {"id": "D2-C20", "d": 2, "front": "Retry policy for transient vs deterministic errors?", "back": "Transient: bounded retries with backoff, then escalate. Deterministic (denied, invalid config): do not retry; fix or escalate."}, {"id": "D2-C21", "d": 2, "front": "How do you roll back a bad agent change before merge?", "back": "Close the draft PR or revert commits on the copilot/ branch; the default branch is unaffected."}, {"id": "D2-C22", "d": 2, "front": "Traceability features of agent commits?", "back": "Authored by Copilot, requester as co-author, signed (Verified), message links to session log; admins get audit log events."}, {"id": "D2-C23", "d": 2, "front": "How can admins restrict which MCP servers are usable?", "back": "Org/enterprise MCP allowlist and registry policies (optionally restricting to registry servers). Verify names in docs."}, {"id": "D3-C01", "d": 3, "front": "Short-term vs long-term vs external memory?", "back": "Short-term: current context window/session. Long-term: persisted across sessions (Copilot Memory, instructions). External: systems of record (issues, PRs, files, databases)."}, {"id": "D3-C02", "d": 3, "front": "What does Copilot Memory store?", "back": "Repository-level facts and user-level preferences."}, {"id": "D3-C03", "d": 3, "front": "How are repo-level facts validated?", "back": "Stored with citations to code; checked against the current branch before use; only validated facts are used."}, {"id": "D3-C04", "d": 3, "front": "Copilot Memory expiry rule?", "back": "Entries unused for 28 days are deleted automatically; successful validation/use can reset the timer."}, {"id": "D3-C05", "d": 3, "front": "Who can cause repo-level facts to be created?", "back": "Users with write access to the repo who have Copilot Memory enabled."}, {"id": "D3-C06", "d": 3, "front": "Who can review and delete repo-level facts?", "back": "Repository owners."}, {"id": "D3-C07", "d": 3, "front": "Who can see user-level preferences?", "back": "Only that user's interactions; the user can view/delete them; admins can export/delete on Business/Enterprise."}, {"id": "D3-C08", "d": 3, "front": "Which features use Copilot Memory?", "back": "Cloud agent, code review, Copilot CLI and agentic autofix. Code review uses repo-level facts only."}, {"id": "D3-C09", "d": 3, "front": "How is Copilot Memory enabled?", "back": "Per user. Org/enterprise admins enable the policy first, then users can opt out. Individual plans: on by default."}, {"id": "D3-C10", "d": 3, "front": "Where should stable conventions live vs task progress?", "back": "Conventions in reviewed instruction files; progress and decisions in durable external artifacts (PR checklist, PROGRESS.md, issue comments)."}, {"id": "D3-C11", "d": 3, "front": "Name 4 durable state artifacts.", "back": "PR description checklist, progress/decision file on the branch, issue comments, explanatory commit messages."}, {"id": "D3-C12", "d": 3, "front": "How should an agent resume interrupted work?", "back": "Read artifacts and diff, verify recorded state against reality, use idempotent steps, honor prior decisions unless superseded with a note."}, {"id": "D3-C13", "d": 3, "front": "What is context drift?", "back": "Gradual divergence from the original intent in long runs: forgotten constraints, scope creep, contradicted decisions."}, {"id": "D3-C14", "d": 3, "front": "How do you detect drift?", "back": "Compare work to acceptance criteria/plan at checkpoints; watch diff size vs scope and violations of instructions."}, {"id": "D3-C15", "d": 3, "front": "How do you correct drift?", "back": "Re-anchor goal and constraints, revert off-scope changes, split the task, restart a fresh session seeded from artifacts."}, {"id": "D3-C16", "d": 3, "front": "How do you share agent state across tools?", "back": "Through repository and GitHub objects and shared memory, not chat history."}, {"id": "D3-C17", "d": 3, "front": "How do you prevent conflicting context?", "back": "One source of truth per fact; resolve contradictions by fixing or deleting one source."}, {"id": "D3-C18", "d": 3, "front": "How do you prevent stale context?", "back": "Validate against current code, expire entries, re-verify before acting."}, {"id": "D3-C19", "d": 3, "front": "Why scope memory to task-relevant info?", "back": "Irrelevant context buries key instructions, raises cost and causes errors; use path-specific instructions and focused links."}, {"id": "D3-C20", "d": 3, "front": "What should a memory pruning/reset policy define?", "back": "Who writes, how validated, when it expires, who can delete, how to reset."}, {"id": "D4-C01", "d": 4, "front": "Outcomes vs operational constraints?", "back": "Outcomes: what must be true (behavior, tests, docs). Constraints: what must not happen (off-limit files, no new deps, budgets)."}, {"id": "D4-C02", "d": 4, "front": "Name 4 quantitative evaluation signals.", "back": "CI/test pass rate, coverage or test-count change, scan findings (CodeQL, lint), diff size vs scope, review iterations, time to merge, revert rate, cost."}, {"id": "D4-C03", "d": 4, "front": "Name 3 qualitative signals.", "back": "Reviewer judgment of correctness/clarity, adherence to conventions, PR description quality, trust to merge."}, {"id": "D4-C04", "d": 4, "front": "What does 'align evaluation with development intent' protect against?", "back": "Gaming metrics, e.g. deleting a failing test or swallowing exceptions so checks go green without solving the real problem."}, {"id": "D4-C05", "d": 4, "front": "Cloud agent's built-in validation tools?", "back": "CodeQL, Advisory Database check for new dependencies, secret scanning, plus Copilot code review. No GHAS license required."}, {"id": "D4-C06", "d": 4, "front": "Where do you inspect what an agent did and saw?", "back": "Session logs (also plans, tool-call traces, outputs, PR timeline, workflow artifacts)."}, {"id": "D4-C07", "d": 4, "front": "Three root-cause classes?", "back": "Reasoning errors, tool misuse, context/environment issues."}, {"id": "D4-C08", "d": 4, "front": "Example of a reasoning error?", "back": "Misreading the requirement, scope creep, ignoring a stated constraint, wrong plan."}, {"id": "D4-C09", "d": 4, "front": "Example of tool misuse?", "back": "Wrong arguments, wrong tool, repeating a failing call, denied tool, MCP server not started."}, {"id": "D4-C10", "d": 4, "front": "Example of context/environment issue?", "back": "Missing dependency, firewall block, stale/conflicting instructions or memory, flaky test."}, {"id": "D4-C11", "d": 4, "front": "Triage questions for a failed run?", "back": "Did it understand the task? Did it call the right tools correctly? Did the environment allow success?"}, {"id": "D4-C12", "d": 4, "front": "Fix for reasoning errors?", "back": "Sharper acceptance criteria, plan validation, smaller tasks, examples."}, {"id": "D4-C13", "d": 4, "front": "Fix for tool misuse?", "back": "Correct tool config/allowlist, instructions on tool usage, remove unneeded tools."}, {"id": "D4-C14", "d": 4, "front": "Fix for environment issues?", "back": "copilot-setup-steps, firewall allowlist, prune or fix stale context, stabilize flaky tests."}, {"id": "D4-C15", "d": 4, "front": "Five tuning levers?", "back": "Instructions, workflows, constraints, memory usage, tool usage/access."}, {"id": "D4-C16", "d": 4, "front": "Tuning loop?", "back": "Evaluation set > baseline > classify failures > change ONE lever > re-run same set > compare > keep/revert."}, {"id": "D4-C17", "d": 4, "front": "Why change one variable at a time?", "back": "So you can attribute the improvement or regression to a specific change."}, {"id": "D4-C18", "d": 4, "front": "Bad tuning moves?", "back": "Tuning from one anecdote, changing many things at once, loosening permissions as a fix, adding instructions for an environment fault."}, {"id": "D4-C19", "d": 4, "front": "How should instructions be written for tuning?", "back": "Specific, testable, non-contradictory, with an explicit verification step (for example run tests before finishing)."}, {"id": "D4-C20", "d": 4, "front": "Best way to compare plan vs result during analysis?", "back": "Line up the plan, tool-call trace and final diff; find the first divergence."}, {"id": "D5-C01", "d": 5, "front": "Orchestrator-worker pattern?", "back": "A coordinator decomposes work, delegates to specialized agents and aggregates results (hub-and-spoke)."}, {"id": "D5-C02", "d": 5, "front": "Sequential pipeline pattern?", "back": "Agents in a chain; each stage consumes the previous output (planner > implementer > tester > reviewer)."}, {"id": "D5-C03", "d": 5, "front": "Parallel fan-out/fan-in?", "back": "Many agents work independently at once, then results are merged."}, {"id": "D5-C04", "d": 5, "front": "Generator-critic (evaluator-optimizer)?", "back": "One agent produces, another critiques, looping until criteria are met."}, {"id": "D5-C05", "d": 5, "front": "Event-driven pattern?", "back": "Agents react to GitHub events such as labels or issue creation."}, {"id": "D5-C06", "d": 5, "front": "How do you isolate parallel agents?", "back": "Separate branches/sessions/worktrees/environments with disjoint file ownership; share only via commits and artifacts."}, {"id": "D5-C07", "d": 5, "front": "Three multi-agent conflict types?", "back": "Overlapping code changes, duplicated effort, contradictory outputs."}, {"id": "D5-C08", "d": 5, "front": "Resolve overlapping code changes?", "back": "Serialize, rebase, re-partition ownership, or integrate via an integrator agent/human."}, {"id": "D5-C09", "d": 5, "front": "Prevent duplicated effort?", "back": "Claim work before starting (assignment, label, sub-issue) and check existing claims."}, {"id": "D5-C10", "d": 5, "front": "Resolve contradictory outputs?", "back": "Escalate to an arbiter (human or designated agent) and record the decision in one place."}, {"id": "D5-C11", "d": 5, "front": "What goes in a hand-off record?", "back": "Who handed what (inputs, outputs, assumptions) to whom, plus decisions and why."}, {"id": "D5-C12", "d": 5, "front": "Artifacts that make multi-agent work auditable?", "back": "One PR per agent task, linked issues, session logs, scan results, decision log."}, {"id": "D5-C13", "d": 5, "front": "Evidence for post-hoc analysis?", "back": "Session logs, commit co-author trails, audit log events, PR/issue timelines."}, {"id": "D5-C14", "d": 5, "front": "Four failure states to detect?", "back": "Failed, partial, stalled, degraded."}, {"id": "D5-C15", "d": 5, "front": "Handling a stalled agent?", "back": "Detect via timeout/heartbeat; cancel, roll back partial work, re-queue or escalate."}, {"id": "D5-C16", "d": 5, "front": "Handling partial execution?", "back": "Resume from a checkpoint idempotently or roll back; do not restart blindly."}, {"id": "D5-C17", "d": 5, "front": "Circuit breaker?", "back": "Stop routing work to an agent that keeps failing/degrading; fall back to a human or alternative while investigating."}, {"id": "D5-C18", "d": 5, "front": "Safely add an agent to a live workflow?", "back": "Define role, tools and hand-off contract; review its definition via PR; pilot on low-risk tasks."}, {"id": "D5-C19", "d": 5, "front": "Safely update or replace an agent?", "back": "Version definitions, roll out gradually, drain or hand off in-flight work, keep hand-off contracts backward compatible."}, {"id": "D5-C20", "d": 5, "front": "Safely retire an agent?", "back": "Stop new routing, finish/reassign in-flight work, preserve logs/PRs/decision records, document the replacement."}, {"id": "D6-C01", "d": 6, "front": "How do you classify agent actions for autonomy?", "back": "By operational, security and compliance risk (and reversibility); assign the lowest safe level of human involvement."}, {"id": "D6-C02", "d": 6, "front": "Goal when assigning autonomy levels?", "back": "Maximize delivery speed while remaining compliant with security and Responsible AI standards."}, {"id": "D6-C03", "d": 6, "front": "Which actions always need explicit authorization or a controlled path?", "back": "Irreversible or compliance-sensitive ones: production deploys, data deletion, secrets and permission changes."}, {"id": "D6-C04", "d": 6, "front": "Instructions vs technical enforcement?", "back": "Instructions are advisory; allowlists, firewall, rulesets, required checks and hooks cannot be bypassed by the model."}, {"id": "D6-C05", "d": 6, "front": "Name five technical guardrails.", "back": "Tool allowlists, firewall, rulesets/branch protection, required reviews/CODEOWNERS, push protection/code scanning, org policies, hooks."}, {"id": "D6-C06", "d": 6, "front": "Least-privilege MCP/token practice?", "back": "Read-only tools and endpoints, fine-grained PAT or GitHub App scoped to specific repos, narrow tools list."}, {"id": "D6-C07", "d": 6, "front": "How do you preserve velocity with guardrails?", "back": "Risk-based approvals at PR level, async review, auto-allow read-only actions, no approvals that do not reduce risk."}, {"id": "D6-C08", "d": 6, "front": "Who can trigger cloud agent?", "back": "Users with write access. Comments from users without write access are never shown to it."}, {"id": "D6-C09", "d": 6, "front": "Cloud agent PR rules?", "back": "Draft PRs need human review and merge; agent cannot mark ready, approve or merge; requester cannot approve."}, {"id": "D6-C10", "d": 6, "front": "Extra approval rule?", "back": "PRs opened under the agent's own identity need one additional approval if the repo already requires approvals (ruleset default; always for branch protection)."}, {"id": "D6-C11", "d": 6, "front": "Workflows on agent PRs?", "back": "Do not run until a user with write access clicks Approve and run workflows (configurable)."}, {"id": "D6-C12", "d": 6, "front": "Prompt-injection mitigation built into cloud agent?", "back": "Hidden characters filtered (for example HTML comments are not passed); non-write users' comments excluded."}, {"id": "D6-C13", "d": 6, "front": "Sensitive-data mitigation?", "back": "Restricted internet access via the firewall (customizable allowlist)."}, {"id": "D6-C14", "d": 6, "front": "Accountability features for agent commits?", "back": "Copilot as author, requester as co-author, signed (Verified), link to session logs; admin audit log events."}, {"id": "D6-C15", "d": 6, "front": "Automation guardrails?", "back": "Attributed to creator, you choose exactly which tools it can use, untrusted-user events ignored by default, workflows still need human approval."}, {"id": "D6-C16", "d": 6, "front": "What decisions require human judgment?", "back": "Ambiguity, business/ethical trade-offs, security-sensitive and irreversible changes."}, {"id": "D6-C17", "d": 6, "front": "How do you gate a production deploy by an agent?", "back": "Protected environment with required reviewers (explicit authorization), plus protected branch and checks."}, {"id": "D6-C18", "d": 6, "front": "Why is 'approve every tool call' bad?", "back": "It adds friction without materially reducing risk; the exam favors risk-proportional controls."}, {"id": "D6-C19", "d": 6, "front": "Who is accountable for merged agent code?", "back": "Humans: reviewers and the team. 'The agent did it' is not a control."}, {"id": "D6-C20", "d": 6, "front": "What does the study guide link for guardrails?", "back": "The Build guardrails tutorial and the Risks and mitigations page for cloud agent."}], "questions": [{"id": "D1-Q01", "d": 1, "type": "single", "q": "Which task is the best first candidate to delegate to a coding agent?", "o": ["Redesign authentication across five services", "Add unit tests for a well-specified utility module that already has CI", "Rotate production database credentials", "Decide next quarter's roadmap priorities"], "a": [1], "e": "It is well-scoped, automatically verifiable and easy to undo via a PR.", "ref": "lessons/01"}, {"id": "D1-Q02", "d": 1, "type": "single", "q": "Agent PRs pass CI but repeatedly miss what the requester wanted. Which gap is most likely?", "o": ["The model is too small", "Tasks lack explicit acceptance criteria and scope", "CI runs too slowly", "Branch names are inconsistent"], "a": [1], "e": "Without objective success criteria the agent optimizes for 'looks done'.", "ref": "lessons/01"}, {"id": "D1-Q03", "d": 1, "type": "single", "q": "Which setup is an autonomy anti-pattern?", "o": ["Agent pushes to its own branch and opens a draft PR", "Agent can merge its own PR to the default branch with no required review", "Agent uses a read-only tool list while planning", "Agent output is linked to a session log"], "a": [1], "e": "Self-approval removes the independent human control that makes autonomy safe.", "ref": "lessons/01"}, {"id": "D1-Q04", "d": 1, "type": "multi", "q": "Select TWO inputs that belong in a well-formed agent task.", "o": ["Acceptance criteria", "Files or areas in scope", "An organization-admin token", "The entire chat history of unrelated projects"], "a": [0, 1], "e": "Criteria and scope bound the work; broad credentials or unrelated history add risk and noise.", "ref": "lessons/01"}, {"id": "D1-Q05", "d": 1, "type": "single", "q": "Requirement: the agent must propose a change plan and must not modify code until a human approves. Best design?", "o": ["One agent with write tools and an instruction saying 'ask first'", "A planner limited to read/search tools that outputs a structured plan, plus an executor enabled only after approval", "Let the agent run, then revert if the plan was wrong", "Disable all tools"], "a": [1], "e": "Tool restriction plus an approval gate technically enforces plan-before-act.", "ref": "lessons/01"}, {"id": "D1-Q06", "d": 1, "type": "single", "q": "Why should an agent emit a structured plan (for example a numbered checklist) rather than free prose?", "o": ["It uses fewer tokens", "It can be validated and compared with the final diff", "Prose cannot be reviewed", "Structured plans bypass approvals"], "a": [1], "e": "Structure makes automated and human validation and later comparison possible.", "ref": "lessons/01"}, {"id": "D1-Q07", "d": 1, "type": "single", "q": "Which artifact best supports inspection in standard development tooling?", "o": ["A private chat transcript on a laptop", "A draft PR with description, commits and a link to the session log", "A verbal summary in standup", "A screenshot in a slide deck"], "a": [1], "e": "PRs, commits and logs live in tools reviewers already use and are auditable.", "ref": "lessons/01"}, {"id": "D1-Q08", "d": 1, "type": "single", "q": "How can you keep humans in control without slowing delivery?", "o": ["Approve every tool call", "Review at the PR boundary and use CODEOWNERS/rulesets for sensitive paths", "Remove all review", "Only review on Fridays"], "a": [1], "e": "Risk-based review points keep control with minimal friction.", "ref": "lessons/01"}, {"id": "D1-Q09", "d": 1, "type": "order", "q": "Put a plan-gated agent workflow in order.", "o": ["Agent executes the approved plan and opens a draft PR", "Task is defined with acceptance criteria", "Plan is validated and approved", "Automated scans and human review of the PR", "Agent produces a structured plan using read-only tools"], "a": [1, 4, 2, 0, 3], "e": "Define, plan (read-only), validate/approve, execute, then scan and review.", "ref": "lessons/01"}, {"id": "D1-Q10", "d": 1, "type": "single", "q": "An agent's plan references a test file that does not exist. Which control would catch this before execution?", "o": ["Plan validation against repository state", "Larger context window", "Faster runners", "Squash merging"], "a": [0], "e": "Validating the plan against the repo catches hallucinated references.", "ref": "lessons/01"}, {"id": "D1-Q11", "d": 1, "type": "single", "q": "Which characteristic most makes a task unsuitable for autonomous delegation?", "o": ["It touches more than one file", "Requirements are ambiguous and there is no automated way to verify the result", "It has existing tests", "It is documented in an issue"], "a": [1], "e": "No verification and unclear intent mean the agent cannot know when it is done.", "ref": "lessons/01"}, {"id": "D1-Q12", "d": 1, "type": "single", "q": "An auditor wants to know how an agent change was produced. Which built-in cloud agent evidence helps most?", "o": ["Session logs linked from the agent's commit messages", "Slack messages", "Developer laptop history", "Browser cookies"], "a": [0], "e": "Agent commits link to session logs; commits also record the requester as co-author.", "ref": "docs.github.com risks-and-mitigations"}, {"id": "D1-Q13", "d": 1, "type": "single", "q": "Which file gives Copilot persistent, repo-wide guidance such as build commands and conventions?", "o": [".github/copilot-instructions.md", "README.txt in /tmp", "package-lock.json", "CODEOWNERS"], "a": [0], "e": "Repo custom instructions live in .github/copilot-instructions.md.", "ref": "docs.github.com custom instructions"}, {"id": "D1-Q14", "d": 1, "type": "single", "q": "How should you decide the degree of autonomy for a dependency-bump agent?", "o": ["Maximum for every agent", "Classify by risk and apply proportional guardrails, for example PR creation allowed and review required", "Always zero autonomy", "Let the agent decide for itself"], "a": [1], "e": "Autonomy is right-sized to risk with guardrails.", "ref": "lessons/01"}, {"id": "D1-Q15", "d": 1, "type": "single", "q": "One mega-agent plans, codes, security-reviews and deploys. What is the primary problem?", "o": ["No separation of duties, so no independent check", "It costs too much", "It cannot write tests", "It needs a newer model"], "a": [0], "e": "Roles should be separated so reviewing is independent of building.", "ref": "lessons/01"}, {"id": "D1-Q16", "d": 1, "type": "single", "q": "Which is the best definition of done for a bug-fix task?", "o": ["Fix the bug", "Failing regression test added and passing, suite green, no new CodeQL alerts, changes limited to the affected module", "Agent says it is finished", "The PR has many commits"], "a": [1], "e": "Objective, checkable criteria beat self-reported completion.", "ref": "lessons/01"}, {"id": "D2-Q01", "d": 2, "type": "single", "q": "Where do you add MCP server JSON for Copilot cloud agent at repository level?", "o": ["Repo Settings > Copilot > MCP servers", "A file named mcp.txt in the repo root", "The pull request description", "Actions workflow env block"], "a": [0], "e": "The repo-level MCP configuration is entered in repository settings.", "ref": "docs.github.com configure-mcp-servers"}, {"id": "D2-Q02", "d": 2, "type": "single", "q": "An MCP server needs an API key. How should it be supplied?", "o": ["Hard-coded in the JSON", "As an Agents secret named with the COPILOT_MCP_ prefix, referenced from env", "In copilot-instructions.md", "In the issue body"], "a": [1], "e": "Only COPILOT_MCP_-prefixed Agents secrets/variables are available to the MCP config.", "ref": "docs.github.com configure-mcp-servers"}, {"id": "D2-Q03", "d": 2, "type": "single", "q": "Which `tools` setting best follows least privilege for a third-party MCP server?", "o": ["[\"*\"]", "An explicit list of specific read-only tools", "An empty string", "Omit the key"], "a": [1], "e": "Copilot uses MCP tools without asking approval, so allowlist only what is needed.", "ref": "docs.github.com configure-mcp-servers"}, {"id": "D2-Q04", "d": 2, "type": "single", "q": "Which `type` values does cloud agent accept for MCP servers?", "o": ["local, stdio, http, sse", "grpc, ws", "docker only", "ftp, smtp"], "a": [0], "e": "The documented values are local, stdio, http and sse.", "ref": "docs.github.com configure-mcp-servers"}, {"id": "D2-Q05", "d": 2, "type": "multi", "q": "Select TWO limitations of MCP support in Copilot cloud agent and code review.", "o": ["Only MCP tools are supported, not resources or prompts", "Remote servers that use OAuth are not supported", "Only one MCP server may be configured", "Local servers are never supported"], "a": [0, 1], "e": "Tools only, and no OAuth-based remote servers.", "ref": "docs.github.com configure-mcp-servers"}, {"id": "D2-Q06", "d": 2, "type": "single", "q": "Which MCP servers are enabled by default for cloud agent?", "o": ["GitHub and Playwright", "Slack and Jira", "Sentry and Notion", "None"], "a": [0], "e": "The GitHub and Playwright MCP servers are on by default.", "ref": "docs.github.com configure-mcp-servers"}, {"id": "D2-Q07", "d": 2, "type": "single", "q": "The default GitHub MCP server token can do what?", "o": ["Read-only access to the current repository", "Write to all repos in the org", "Admin access to the org", "Nothing"], "a": [0], "e": "It is a specially scoped read-only token for the current repository.", "ref": "docs.github.com configure-mcp-servers"}, {"id": "D2-Q08", "d": 2, "type": "single", "q": "Which remote GitHub MCP URL provides the read-only variant?", "o": ["https://api.githubcopilot.com/mcp/readonly", "https://github.com/mcp/rw", "https://api.github.com/mcp", "https://mcp.github.io/readonly"], "a": [0], "e": "The documented read-only endpoint is /mcp/readonly.", "ref": "docs.github.com configure-mcp-servers"}, {"id": "D2-Q09", "d": 2, "type": "single", "q": "Which header selects which toolsets the remote GitHub MCP server exposes?", "o": ["X-MCP-Toolsets", "Accept-Toolsets", "X-GitHub-Scope", "Authorization-Scope"], "a": [0], "e": "X-MCP-Toolsets lists toolsets such as repos,issues,pull_requests.", "ref": "docs.github.com configure-mcp-servers"}, {"id": "D2-Q10", "d": 2, "type": "single", "q": "How do you confirm your MCP servers actually started for a cloud agent run?", "o": ["Check the 'Start MCP Servers' step in the session log", "Restart GitHub", "Look at the repo's star count", "Read the Actions billing page"], "a": [0], "e": "The session log's Start MCP Servers step lists started servers and their tools.", "ref": "docs.github.com configure-mcp-servers"}, {"id": "D2-Q11", "d": 2, "type": "single", "q": "Your MCP server needs `uv`, which is not on the default runner. What is the right fix?", "o": ["Disable the MCP server", "Install uv in copilot-setup-steps.yml", "Switch to a different repo", "Ask the agent to download it at random times"], "a": [1], "e": "Setup steps prepare the agent's environment before it starts.", "ref": "docs.github.com configure-mcp-servers"}, {"id": "D2-Q12", "d": 2, "type": "single", "q": "What file and job name configure the cloud agent environment?", "o": [".github/workflows/copilot-setup-steps.yml with a job named copilot-setup-steps", "agent.yml with job setup", "Dockerfile.agent", "setup.sh in /tmp"], "a": [0], "e": "The workflow must contain a job named copilot-setup-steps.", "ref": "docs.github.com customize-the-agent-environment"}, {"id": "D2-Q13", "d": 2, "type": "single", "q": "The agent cannot reach a package host because of the firewall. Best response?", "o": ["Disable the firewall entirely", "Add the specific host to the custom allowlist", "Give the agent an org-admin token", "Ignore failing builds"], "a": [1], "e": "Allowlist only what is required; keep the firewall on.", "ref": "docs.github.com customize-the-firewall"}, {"id": "D2-Q14", "d": 2, "type": "single", "q": "Which branch can cloud agent push to when started from an issue?", "o": ["Any branch it chooses", "A single new copilot/ branch", "Only main", "Any protected branch"], "a": [1], "e": "It can push to one branch; branch protections and required checks still apply.", "ref": "docs.github.com risks-and-mitigations"}, {"id": "D2-Q15", "d": 2, "type": "single", "q": "Which action can cloud agent NOT perform?", "o": ["Create a branch", "Open a draft PR", "Approve and merge its own PR", "Push commits to its copilot/ branch"], "a": [2], "e": "It cannot mark Ready for review, approve or merge.", "ref": "docs.github.com risks-and-mitigations"}, {"id": "D2-Q16", "d": 2, "type": "single", "q": "By default, when do Actions workflows run on an agent's PR?", "o": ["Immediately", "After a user with write access clicks Approve and run workflows", "Never", "Only on Sundays"], "a": [1], "e": "Workflow runs wait for human approval by default (configurable).", "ref": "docs.github.com risks-and-mitigations"}, {"id": "D2-Q17", "d": 2, "type": "single", "q": "A tool call fails intermittently with HTTP 503. Best handling?", "o": ["Retry forever", "Bounded retries with backoff, then escalate", "Ignore and continue", "Delete the repo"], "a": [1], "e": "Transient errors justify limited retries; unbounded retries hide problems and burn cost.", "ref": "lessons/02"}, {"id": "D2-Q18", "d": 2, "type": "single", "q": "A tool call is rejected because the tool is not on the allowlist. What now?", "o": ["Retry 10 times", "Do not retry; fix permissions deliberately or escalate to a human", "Switch to wildcard '*' immediately", "Hide the error"], "a": [1], "e": "Deterministic denials do not self-heal; change permissions only through a reviewed decision.", "ref": "lessons/02"}, {"id": "D2-Q19", "d": 2, "type": "single", "q": "The agent's PR contains a bad change. What is the cleanest rollback before merge?", "o": ["Force-push to main", "Close the draft PR or revert commits on the copilot/ branch", "Delete the repository", "Disable Copilot org-wide"], "a": [1], "e": "Branch isolation means main is unaffected; discard or revert the branch work.", "ref": "lessons/02"}, {"id": "D2-Q20", "d": 2, "type": "single", "q": "Which of these provides traceability for a cloud agent commit?", "o": ["Commit authored by Copilot, requester as co-author, signed, message links the session log", "An unsigned commit with no link", "A commit authored by the admin", "A commit squashed to hide authorship"], "a": [0], "e": "These attributes support accountability and auditing.", "ref": "docs.github.com risks-and-mitigations"}, {"id": "D2-Q21", "d": 2, "type": "single", "q": "An enterprise wants only vetted MCP servers to be usable by Copilot. What should an admin use?", "o": ["An MCP allowlist and/or registry policy", "Ask developers to be careful", "Disable all Copilot features", "Edit each developer laptop"], "a": [0], "e": "Allowlist and registry controls govern which MCP servers are permitted. Verify exact policy names in docs.", "ref": "docs.github.com configure-enterprise-allowlist"}, {"id": "D3-Q01", "d": 3, "type": "single", "q": "Which describes short-term agent memory?", "o": ["Content in the current session's context window", "Facts stored for 28 days", "A row in an external database", "A GitHub issue"], "a": [0], "e": "Short-term memory is the active context for the current session.", "ref": "lessons/03"}, {"id": "D3-Q02", "d": 3, "type": "single", "q": "Copilot Memory stores which two categories of information?", "o": ["Repository-level facts and user-level preferences", "Secrets and tokens", "Billing data and licenses", "Binary build artifacts"], "a": [0], "e": "Repo facts and user preferences are the two stored types.", "ref": "docs.github.com copilot-memory"}, {"id": "D3-Q03", "d": 3, "type": "single", "q": "After how many days are unused Copilot Memory entries deleted automatically?", "o": ["7", "28", "90", "365"], "a": [1], "e": "Unused entries are removed after 28 days.", "ref": "docs.github.com copilot-memory"}, {"id": "D3-Q04", "d": 3, "type": "single", "q": "Before Copilot uses a stored repository fact, what happens?", "o": ["Its citations are checked against the current branch", "It is sent to the repo owner for approval", "It is copied to all repositories", "Nothing"], "a": [0], "e": "Only facts validated against the current branch are used.", "ref": "docs.github.com copilot-memory"}, {"id": "D3-Q05", "d": 3, "type": "single", "q": "Which statement about user-level preferences is correct?", "o": ["They apply to all users in the org", "They are only available in that user's own interactions", "They are used by code review", "They are stored in the repo"], "a": [1], "e": "User-level preferences are tied to the user; code review uses repo-level facts only.", "ref": "docs.github.com copilot-memory"}, {"id": "D3-Q06", "d": 3, "type": "single", "q": "Repository-level facts are created in response to activity by whom?", "o": ["Anyone who views the repo", "Users with write access who have Copilot Memory enabled", "Only enterprise owners", "Bots only"], "a": [1], "e": "Write access plus Memory enabled is required.", "ref": "docs.github.com copilot-memory"}, {"id": "D3-Q07", "d": 3, "type": "single", "q": "A long task is interrupted. What best enables resuming without repeating or diverging?", "o": ["Rely on the model to remember", "Persist progress and decisions as durable artifacts and have the agent read and verify them first", "Restart from scratch each time", "Delete the branch"], "a": [1], "e": "Durable artifacts plus verification give reliable resumption.", "ref": "lessons/03"}, {"id": "D3-Q08", "d": 3, "type": "single", "q": "How do you best detect drift in an extended agent run?", "o": ["Compare current work against the acceptance criteria and plan at checkpoints", "Hope for the best", "Increase the context window only", "Count commits"], "a": [0], "e": "Checkpoint comparison catches scope creep and contradicted decisions.", "ref": "lessons/03"}, {"id": "D3-Q09", "d": 3, "type": "single", "q": "A remembered fact says tests run with `npm test`, but the repo migrated to pnpm. What mechanism helps avoid using the stale fact?", "o": ["Validation against the current branch and expiry of unused entries", "Larger model", "More instructions", "Disabling CI"], "a": [0], "e": "Citation validation against current code plus expiry limit stale context.", "ref": "docs.github.com copilot-memory"}, {"id": "D3-Q10", "d": 3, "type": "single", "q": "Two tools hold contradictory conventions and agents behave inconsistently. Best fix?", "o": ["Keep both and hope", "Keep one versioned source of truth and remove or correct the other", "Add a third source", "Disable all instructions"], "a": [1], "e": "Single source of truth prevents conflicting context.", "ref": "lessons/03"}, {"id": "D3-Q11", "d": 3, "type": "multi", "q": "Select TWO ways to scope agent context to what a task needs.", "o": ["Path-specific instructions using applyTo", "Short, specific repository instructions", "Paste the entire company wiki into instructions", "Keep every session transcript forever"], "a": [0, 1], "e": "Targeted, concise context avoids noise and drift.", "ref": "lessons/03"}, {"id": "D4-Q01", "d": 4, "type": "single", "q": "Which set is the best combination of quantitative evaluation signals for a bug-fix agent?", "o": ["CI pass rate, coverage change, CodeQL alerts, review iterations", "Number of emojis in the PR", "Commit author count", "Branch name length"], "a": [0], "e": "These are objective, relevant outcome signals.", "ref": "lessons/04"}, {"id": "D4-Q02", "d": 4, "type": "single", "q": "An agent makes CI green by deleting a failing test. Which evaluation criterion best catches this?", "o": ["Check that test count/coverage did not decrease and review the change's intent", "Only look at the green checkmark", "Count commits", "Measure PR title length"], "a": [0], "e": "Signals must be aligned to intent, not just pass/fail.", "ref": "lessons/04"}, {"id": "D4-Q03", "d": 4, "type": "single", "q": "Which are among the tools cloud agent uses by default to validate its own code?", "o": ["CodeQL, Advisory Database dependency checks, secret scanning, Copilot code review", "Only a spell checker", "Manual QA by GitHub staff", "None"], "a": [0], "e": "These are the documented built-in validation tools.", "ref": "docs.github.com risks-and-mitigations"}, {"id": "D4-Q04", "d": 4, "type": "single", "q": "Does cloud agent's built-in security validation require a GitHub Advanced Security license?", "o": ["Yes", "No", "Only for private repos", "Only for enterprise"], "a": [1], "e": "It does not require GHAS, Code Security or Secret Protection licenses.", "ref": "docs.github.com risks-and-mitigations"}, {"id": "D4-Q05", "d": 4, "type": "single", "q": "Where do you look first to understand what a cloud agent actually did during a run?", "o": ["Session logs", "Billing page", "Repo stars", "Organization chart"], "a": [0], "e": "Session logs record the agent's steps and tool activity.", "ref": "docs.github.com manage-and-track-agents"}, {"id": "D4-Q06", "d": 4, "type": "single", "q": "The agent repeatedly calls a tool with an invalid flag. Root-cause class?", "o": ["Tool misuse", "Environment issue", "Network outage", "Billing issue"], "a": [0], "e": "Right intent, wrong tool usage.", "ref": "lessons/04"}, {"id": "D4-Q07", "d": 4, "type": "single", "q": "Builds fail because a required dependency is missing on the runner. Root-cause class and fix?", "o": ["Context/environment issue; add it to copilot-setup-steps", "Reasoning error; rewrite the issue", "Tool misuse; remove the tool", "Model error; change the model"], "a": [0], "e": "The environment prevented success; setup steps fix it.", "ref": "lessons/04"}, {"id": "D4-Q08", "d": 4, "type": "single", "q": "The agent implemented a feature nobody requested because the issue was ambiguous. Class and fix?", "o": ["Reasoning error; clarify acceptance criteria and validate the plan first", "Environment issue; allowlist a host", "Tool misuse; use another MCP", "None"], "a": [0], "e": "Ambiguity leads to misinterpretation; sharpen inputs and gate on a plan.", "ref": "lessons/04"}, {"id": "D4-Q09", "d": 4, "type": "single", "q": "What is the soundest tuning approach?", "o": ["Change one lever, re-run the same evaluation set, compare signals", "Change five things and see what happens", "Tune from one example", "Loosen every permission"], "a": [0], "e": "Single-variable changes against a fixed set give attributable results.", "ref": "lessons/04"}, {"id": "D4-Q10", "d": 4, "type": "single", "q": "The MCP tools never appear in the session. What do you check first?", "o": ["The 'Start MCP Servers' step and MCP configuration/secrets", "The font settings", "The PR title", "The number of reviewers"], "a": [0], "e": "This is a tool/config fault visible in the startup step.", "ref": "docs.github.com configure-mcp-servers"}, {"id": "D4-Q11", "d": 4, "type": "single", "q": "The instructions file is thousands of lines with contradictory rules and results are inconsistent. Best tune?", "o": ["Trim, de-duplicate, make rules specific and scope with applyTo", "Add more rules", "Delete tests", "Disable review"], "a": [0], "e": "Clear, focused, non-conflicting instructions improve reliability.", "ref": "lessons/04"}, {"id": "D4-Q12", "d": 4, "type": "multi", "q": "Select TWO qualitative evaluation signals.", "o": ["Reviewer judgment that the PR explanation is clear", "Adherence to team conventions in code review", "Test pass rate", "Number of CodeQL alerts"], "a": [0, 1], "e": "The other two are quantitative.", "ref": "lessons/04"}, {"id": "D4-Q13", "d": 4, "type": "single", "q": "The agent makes many unnecessary and risky tool calls. Which tuning lever fits best?", "o": ["Narrow the tool allowlist and describe when to use each tool", "Give it more tools", "Disable CI", "Remove all instructions"], "a": [0], "e": "Refining tool access reduces misuse and risk.", "ref": "lessons/04"}, {"id": "D4-Q14", "d": 4, "type": "single", "q": "Which analysis technique best finds where a run went wrong?", "o": ["Line up plan, tool-call trace and final diff to find the first divergence", "Re-run blindly", "Read the README", "Count tokens"], "a": [0], "e": "The first divergence points to the root cause.", "ref": "lessons/04"}, {"id": "D4-Q15", "d": 4, "type": "single", "q": "Which signal is generated automatically by a scanning tool?", "o": ["CodeQL alerts", "Reviewer opinion", "Team morale", "PR title"], "a": [0], "e": "Scans such as CodeQL produce objective findings.", "ref": "docs.github.com risks-and-mitigations"}, {"id": "D5-Q01", "d": 5, "type": "single", "q": "A coordinator splits a feature into three independent modules and delegates each to a specialist agent. Which pattern is this?", "o": ["Orchestrator-worker", "Generator-critic", "Event-driven only", "Sequential pipeline only"], "a": [0], "e": "One coordinator decomposes, delegates and aggregates.", "ref": "lessons/05"}, {"id": "D5-Q02", "d": 5, "type": "single", "q": "An implementer agent's output is reviewed by a reviewer agent, and the loop repeats until criteria are met. Which pattern?", "o": ["Generator-critic", "Fan-out", "Hub only", "Pipeline without feedback"], "a": [0], "e": "Producer plus critic loop is generator-critic.", "ref": "lessons/05"}, {"id": "D5-Q03", "d": 5, "type": "single", "q": "Three agents edit the same files in parallel and constantly conflict. Best fix?", "o": ["Isolate on separate branches with disjoint file ownership", "Let them overwrite each other", "Run them faster", "Merge everything unreviewed"], "a": [0], "e": "Isolation plus ownership partitioning prevents overlap.", "ref": "lessons/05"}, {"id": "D5-Q04", "d": 5, "type": "single", "q": "Two agents built the same feature in separate PRs. Which practice prevents duplicated effort?", "o": ["Claim work items (assignment, label, sub-issue) before starting", "Hide the issue list", "Disable CI", "Randomly pick tasks"], "a": [0], "e": "Explicit claims make work visible and exclusive.", "ref": "lessons/05"}, {"id": "D5-Q05", "d": 5, "type": "single", "q": "Two agents produce contradictory designs. Best resolution?", "o": ["Escalate to an arbiter (human or designated agent) and record the decision", "Merge both", "Delete both", "Pick whichever finished first"], "a": [0], "e": "A single arbiter with a recorded decision keeps one source of truth.", "ref": "lessons/05"}, {"id": "D5-Q06", "d": 5, "type": "single", "q": "Which approach makes a multi-agent workflow review- and audit-friendly?", "o": ["Each agent task yields a PR, logs and a hand-off record linked in one coordination issue", "Agents communicate only in private chats", "No logs", "One giant commit"], "a": [0], "e": "Linked artifacts in standard tooling support audit.", "ref": "lessons/05"}, {"id": "D5-Q07", "d": 5, "type": "single", "q": "Which evidence best reconstructs a multi-agent timeline after an incident?", "o": ["Session logs, commit co-author trails and audit log events", "Memory of the engineers", "Marketing dashboards", "Lunch receipts"], "a": [0], "e": "These are authoritative, timestamped records.", "ref": "docs.github.com risks-and-mitigations"}, {"id": "D5-Q08", "d": 5, "type": "single", "q": "An agent has shown no progress for much longer than expected. What is the best response?", "o": ["Detect via timeout, cancel, roll back partial work and re-queue or escalate", "Wait forever", "Merge its partial work", "Add more agents to the same task"], "a": [0], "e": "Timeout-based detection with clean-up and escalation handles stalls.", "ref": "lessons/05"}, {"id": "D5-Q09", "d": 5, "type": "single", "q": "An agent completed three of five subtasks before failing. Best recovery?", "o": ["Resume from the checkpoint idempotently or roll back; do not restart blindly", "Always restart from zero", "Ignore the failure", "Merge as is"], "a": [0], "e": "Checkpoint resume avoids wasted or duplicated work.", "ref": "lessons/05"}, {"id": "D5-Q10", "d": 5, "type": "single", "q": "How do you add a new agent to a live workflow with minimal disruption?", "o": ["Define its hand-off contract, review its definition by PR and pilot it on low-risk tasks", "Replace all agents at once", "Skip review", "Disable logging"], "a": [0], "e": "Reviewed definition plus staged rollout limits blast radius.", "ref": "lessons/05"}, {"id": "D5-Q11", "d": 5, "type": "single", "q": "You must replace an agent while tasks are in flight. Best approach?", "o": ["Version the new definition, drain or hand off in-flight work, keep hand-off contracts compatible", "Kill in-flight work without notes", "Change the contract silently", "Delete history"], "a": [0], "e": "Gradual, compatible replacement avoids breaking active workflows.", "ref": "lessons/05"}, {"id": "D5-Q12", "d": 5, "type": "single", "q": "How do you retire an agent while keeping auditability?", "o": ["Stop routing, finish or reassign work, preserve logs, PRs and decisions", "Delete all its PRs and logs", "Rename it", "Ignore"], "a": [0], "e": "Audit records must outlive the agent.", "ref": "lessons/05"}, {"id": "D5-Q13", "d": 5, "type": "order", "q": "Order a sequential pipeline for a feature.", "o": ["Human merges", "Implementer writes code and tests", "Planner produces a plan", "Reviewer agent critiques the PR", "Tester agent runs and extends tests"], "a": [2, 1, 4, 3, 0], "e": "Plan, implement, test, review, then human merge.", "ref": "lessons/05"}, {"id": "D5-Q14", "d": 5, "type": "single", "q": "An agent's failure rate keeps rising and its output quality drops. Which recovery pattern fits?", "o": ["Circuit breaker: pause routing to it and fall back to a human or alternative while investigating", "Send it even more tasks", "Remove logging", "Raise its permissions"], "a": [0], "e": "Containing a degraded component protects the workflow.", "ref": "lessons/05"}, {"id": "D5-Q15", "d": 5, "type": "single", "q": "Which property ensures parallel agents do not see each other's uncommitted changes?", "o": ["Separate branches/working copies/environments", "One shared folder", "Shared clipboard", "Same session"], "a": [0], "e": "Isolation separates state until changes are committed and reviewed.", "ref": "lessons/05"}, {"id": "D6-Q01", "d": 6, "type": "single", "q": "Which agent action most clearly requires explicit human authorization or a controlled approval path?", "o": ["Reading a source file", "Creating a draft PR", "Deploying to production", "Listing open issues"], "a": [2], "e": "Production deploys are high-risk and hard to reverse.", "ref": "lessons/06"}, {"id": "D6-Q02", "d": 6, "type": "single", "q": "How should you right-size human intervention?", "o": ["Approve every action", "Approve nothing", "Match approvals to risk and drop approvals that do not reduce risk", "Approve only on Fridays"], "a": [2], "e": "Risk-proportional approvals keep safety and speed.", "ref": "lessons/06"}, {"id": "D6-Q03", "d": 6, "type": "single", "q": "A developer asks cloud agent to create a PR. Who cannot approve that PR to satisfy required approvals?", "o": ["The developer who requested it", "Any reviewer", "The CODEOWNER", "No one"], "a": [0], "e": "The requester is prevented from approving, preserving required-approval controls.", "ref": "docs.github.com risks-and-mitigations"}, {"id": "D6-Q04", "d": 6, "type": "single", "q": "What additional approval applies when a cloud agent opens a PR under its own identity?", "o": ["One extra approval beyond required approvals, when approvals are already required", "No approvals at all", "Two security team approvals always", "It auto-merges"], "a": [0], "e": "Extra approval is required for unattributed PRs (rulesets default; branch protection always).", "ref": "docs.github.com risks-and-mitigations"}, {"id": "D6-Q05", "d": 6, "type": "single", "q": "An issue contains instructions hidden in an HTML comment. What does cloud agent do?", "o": ["Hidden characters/HTML comments are filtered and not passed to the agent", "It obeys them first", "It forwards them to admins", "It merges immediately"], "a": [0], "e": "Hidden content is filtered as a prompt injection mitigation.", "ref": "docs.github.com risks-and-mitigations"}, {"id": "D6-Q06", "d": 6, "type": "single", "q": "A user without write access comments on an issue assigned to the agent. What happens?", "o": ["The comment is never presented to the agent", "The agent runs it as admin", "The agent merges", "The repo is deleted"], "a": [0], "e": "Only write-access users can influence the agent.", "ref": "docs.github.com risks-and-mitigations"}, {"id": "D6-Q07", "d": 6, "type": "single", "q": "Which MCP setup best follows least privilege?", "o": ["Read-only endpoint, named read-only tools, fine-grained PAT limited to specific repos", "Org-admin PAT with wildcard tools", "Anonymous access", "Shared personal token in the repo"], "a": [0], "e": "Narrow tools and scoped credentials limit blast radius.", "ref": "docs.github.com configure-mcp-servers"}, {"id": "D6-Q08", "d": 6, "type": "single", "q": "Policy: agents must never modify .github/workflows. Which is the strongest control?", "o": ["A line in the instructions asking it not to", "Required reviewers on that path via ruleset/CODEOWNERS plus required checks", "Hope", "A comment in the PR"], "a": [1], "e": "Technical enforcement beats advisory instructions.", "ref": "lessons/06"}, {"id": "D6-Q09", "d": 6, "type": "single", "q": "An agent must be able to deploy to production when approved. Best pattern?", "o": ["Deploy job targeting a protected environment with required reviewers", "Give the agent permanent production credentials", "Let it deploy any time", "Email the deployment key"], "a": [0], "e": "Protected environments provide explicit authorization on irreversible actions.", "ref": "lessons/06"}, {"id": "D6-Q10", "d": 6, "type": "single", "q": "How does GitHub limit prompt-injection risk in automations that run on events?", "o": ["You choose exactly which tools it can use, and events from users without write access are ignored by default", "Nothing", "Automations ignore all tools", "Automations run as admin"], "a": [0], "e": "Tool scoping and untrusted-event filtering limit what injected content can do.", "ref": "docs.github.com risks-and-mitigations"}, {"id": "D6-Q11", "d": 6, "type": "single", "q": "What visibility do administrators get into agent activity?", "o": ["Session logs and audit log events", "None", "Only Slack messages", "Only billing totals"], "a": [0], "e": "Session logs and audit events support oversight and audit.", "ref": "docs.github.com risks-and-mitigations"}, {"id": "D6-Q12", "d": 6, "type": "single", "q": "Which control most harms delivery speed without reducing risk?", "o": ["Requiring human approval for every read-only tool call", "Required review of PRs touching auth code", "Protected environment for production deploys", "Secret scanning on pushes"], "a": [0], "e": "Approvals on low-risk, read-only actions add friction without benefit.", "ref": "lessons/06"}]};
